function accSheet(id){const a=adm.find(x=>x.id===id);if(!a)return;const pending=c=>Number((a.pending&&a.pending[c])||a["pending"+c.charAt(0).toUpperCase()+c.slice(1)]||0),verified=isAccountVerified(a);sheet(`<div class="adminProfileHero" style="position:sticky;top:-1px;z-index:5;margin:0 0 14px;padding:13px 12px 11px;background:linear-gradient(145deg,#20134f 0%,#4b2fc0 58%,#7659e8 100%);color:#fff;border:1px solid #ffffff20;border-radius:24px;box-shadow:0 10px 24px #24165a45"><div class="admin-profile-head"><div style="min-width:0"><div class="admin-profile-eyebrow">ملف المستخدم</div><div class="admin-profile-name"><h2>${esc(a.fullname||a.username)} ${verified?BADGE(16):""}</h2><button class="admin-profile-copyname" onclick="copyAdminValue('${id}','name')" aria-label="نسخ الاسم">${I("copy",13)}</button></div></div><span class="admin-profile-status">${adminUserActive(a)?"نشط":a.banned?"محظور":a.frozen?"مجمّد":"غير نشط"}</span></div><div class="admin-profile-grid"><button class="admin-profile-pill" onclick="copyAdminValue('${id}','id')"><span>${esc(accountNo(a))}</span>${I("copy",13)}</button><button class="admin-profile-pill" onclick="copyAdminValue('${id}','email')"><span>${esc(a.email||"بدون بريد")}</span>${I("copy",13)}</button><button class="admin-profile-pill" onclick="copyAdminValue('${id}','phone')"><span>${esc(a.phone||"بدون هاتف")}</span>${I("copy",13)}</button><span class="admin-profile-pill admin-profile-idstate">${isValidSyrianNationalId(a.nationalId)?"الرقم الوطني: صيغة 11 خانة صحيحة":"الرقم الوطني: غير مستوفٍ"}</span></div><div class="admin-profile-tags"><span>${verified?"موثّق":"غير موثّق"}</span><span>${a.balanceSuspended?"تعليق الرصيد مفعّل":"الرصيد غير معلّق"}</span></div></div>
<div class="admin-pending-panel"><div class="admin-pending-head"><b>الرصيد المعلّق</b><small>حسب العملة</small></div><div class="admin-pending-grid"><div class="admin-pending-item"><small>${CS.usd}</small><b>${fmt(pending("usd"))}</b></div><div class="admin-pending-item"><small>${CS.syp}</small><b>${fmt(pending("syp"))}</b></div><div class="admin-pending-item"><small>${CS.try}</small><b>${fmt(pending("try"))}</b></div></div><small class="admin-pending-note">${a.balanceSuspended?"التعليق مفعّل؛ يمكنك رفعه أو إبقاؤه كما هو.":"الرصيد غير معلّق؛ يمكنك تعليقه أو إبقاء الحالة كما هي."}</small><div class="admin-pending-actions"><button onclick="releaseBalanceHold('${id}')">${I("wallet-cards",14)} نقل المعلّق إلى المتاح</button><button onclick="${a.balanceSuspended?`releaseBalanceHold('${id}')`:`act('${id}',{balanceSuspended:true})`}">${I("pause-circle",14)}${a.balanceSuspended?"رفع تعليق الرصيد ونقل المبلغ":"تعليق الرصيد"}</button><button onclick="sheet(null)">${I("check",14)}إبقاء الحالة كما هي</button></div></div>
<div class="rbtns" style="grid-template-columns:1fr"><button ${!a.verified&&!isValidSyrianNationalId(a.nationalId)?"disabled":""} onclick="act('${id}',{verified:${!a.verified}})">${I("badge-check")}${a.verified?"إلغاء التوثيق":isValidSyrianNationalId(a.nationalId)?"توثيق الحساب":"أدخل رقمًا وطنيًا صحيحًا أولًا"}</button></div>
<div class="rbtns" style="grid-template-columns:1fr 1fr;margin-top:8px"><button onclick="act('${id}',{banned:${!a.banned}})">${I("ban")}${a.banned?"إلغاء الحظر":"حظر الحساب"}</button><button onclick="sendPwReset('${encodeURIComponent(a.email||"")}')">${I("key-round")}إرسال رابط كلمة السر</button></div>
<div style="margin-top:10px"><input id="ah" placeholder="رقم هاتف جديد" style="direction:ltr;text-align:right"><button class="btn g" onclick="setFld('${id}','ah','phone')">حفظ رقم الهاتف</button></div><div style="margin-top:8px"><input id="ae" value="${esc(a.email||"")}" readonly placeholder="البريد الإلكتروني" style="direction:ltr;text-align:right;background:var(--bg);opacity:.75"><div class="lab">البريد الإلكتروني ثابت ولا يمكن ربطه بأكثر من رقم IBAN.</div></div><div class="msg" id="bm" style="margin-top:10px"></div><div style="margin-top:10px;border-top:1px solid var(--line);padding-top:10px"><b>تعديل الرصيد</b><label class="lab" style="display:block;text-align:right;margin-top:8px">العملة</label><button class="btn g" id="bclabel" style="text-align:right;margin-bottom:10px" onclick="chooseAdminCurrency('${id}')">${CN[adminCurrency]} <span style="float:left;color:var(--pri)">⌄</span></button><input id="ba" type="number" inputmode="decimal" placeholder="المبلغ"><div class="rbtns" style="grid-template-columns:1fr 1fr"><button onclick="balanceAdjust('${id}',1)">تعزيز الرصيد</button><button onclick="balanceAdjust('${id}',-1)">خصم من الرصيد</button></div></div><button class="btn" id="dl" style="margin-top:10px;background:var(--bad)" onclick="delAcc('${id}')">حذف الحساب</button>`)}
